I'm now integrating the `onSaveDraft` prop into the `HeaderActions` component, adding the new "Save Draft" button itself. I've updated `ResumeBuilder` to include a `handleSaveDraft` function to be passed down. The focus is to make the button function correctly and trigger the relevant changes. The next step is to test the integration and ensure the "Save Draft" doesn't affect the existing autosave logic.

```javascript
import React, { useState, useEffect } from 'react';
import HeaderActions from './HeaderActions';

interface ResumeBuilderProps {
  // ... other props ...
}

const ResumeBuilder: React.FC<ResumeBuilderProps> = ({ 
  // ... other props ...
}) => {
  const [formData, setFormData] = useState({});
  const [saveState, setSaveState] = useState<'idle' | 'saving' | 'saved'>('idle');

  const handleSaveDraft = () => {
    // Save formData to local storage
    localStorage.setItem('draftResume', JSON.stringify(formData));
    // Optionally: show a subtle toast
  };

  useEffect(() => {
    // Autosave based on formData changes
    const timeoutId = setTimeout(() => {
      // Set saving state
      setSaveState('saving');
      // Simulated save to external API
      setTimeout(() => {
        // Set saved state
        setSaveState('saved');
        // Reset to idle after 1 second
        setTimeout(() => setSaveState('idle'), 1000);
      }, 1000);
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [formData]);

  return (
    // ... rest of the component ...
    <HeaderActions
      // ... other props ...
      saveState={saveState}
      onSaveDraft={handleSaveDraft}
    />
  );
};

export default ResumeBuilder;
```

